<script setup lang="ts">
import {ref,reactive,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import {createIsmClient,type components} from '@ism/api-client';
type Plan=components['schemas']['PackagePlan'];type Version=components['schemas']['PackageVersion'];type Grant=components['schemas']['PackageModuleGrant'];
const props=defineProps<{token?:string;plan:Plan|null;canManage:boolean;canPublish:boolean}>();const emit=defineEmits<{close:[];changed:[]}>();
const client=createIsmClient({getAccessToken:()=>props.token});
const plan=ref(props.plan),selected=ref<Version>(),options=ref<components['schemas']['PackageModuleOption'][]>([]);
const form=reactive({code:'',name:'',versionNo:1,versionName:''});const grants=ref<{code:string;enabled:boolean;quotas:{code:string;value:string}[]}[]>([]);
const busy=ref(false),loading=ref(false),unknown=ref(false),error=ref(''),notice=ref(''),validated=ref(false),confirmed=ref(false),errorBox=ref<HTMLElement>(),firstInput=ref<HTMLInputElement>();
let mounted=true;type Attempt=({kind:'create';body:components['schemas']['CreatePackage']}|{kind:'version';id:string;body:components['schemas']['CreatePackageVersion']}|{kind:'update';id:string;body:components['schemas']['UpdatePackageVersion']}|{kind:'publish';id:string;body:components['schemas']['PublishPackageVersion']})&{key:string};let attempt:Attempt|null=null;
const snapshot=ref('');const editingSnapshot=()=>JSON.stringify({name:form.versionName,versionNo:form.versionNo,grants:grants.value});
const dirty=computed(()=>!!selected.value&&snapshot.value!==editingSnapshot());
watch(()=>editingSnapshot(),()=>{validated.value=false;confirmed.value=false;});
watch(error,async value=>{if(value){await nextTick();errorBox.value?.focus();}});
function select(v?:Version){if(busy.value||unknown.value)return;applySelection(v);}
function applySelection(v?:Version){selected.value=v;form.versionNo=v?.versionNo??Math.max(0,...(plan.value?.versions.map(v=>v.versionNo)??[]))+1;form.versionName=v?.name??'';grants.value=[...(v?.modules.map(m=>({code:m.moduleCode,enabled:m.enabled,quotas:Object.entries(m.quotas).map(([code,value])=>({code,value:String(value)}))}))??[]),...options.value.filter(o=>!v?.modules.some(m=>m.moduleCode===o.code)).map(m=>({code:m.code,enabled:false,quotas:[]}))];snapshot.value=editingSnapshot();validated.value=false;confirmed.value=false;notice.value='';error.value='';}
async function load(){if(unknown.value||busy.value)return;loading.value=true;error.value='';const token=props.token;try{if(props.canManage){const r=await client.GET('/console/package-modules');if(!mounted||token!==props.token)return;if(r.error){error.value=r.error.error.message;return;}options.value=r.data.data;}if(plan.value){const r=await client.GET('/console/packages/{id}',{params:{path:{id:plan.value.id}}});if(!mounted||token!==props.token)return;if(r.error){error.value=r.error.error.message;return;}plan.value=r.data.data;}select(plan.value?.versions.find(v=>v.id===selected.value?.id));}catch{if(mounted&&token===props.token)error.value='配置读取失败，请重新读取';}finally{if(mounted&&token===props.token)loading.value=false;}}
function modules():Grant[]|null{const enabled=grants.value.filter(m=>m.enabled);if(!enabled.length){error.value='至少启用一个模块';return null;}const result:Grant[]=[];for(const m of grants.value){const quotas:Record<string,number>={};for(const q of m.quotas){if(!/^[A-Z][A-Z0-9_]{0,63}$/.test(q.code)||!/^\d+$/.test(q.value)||!Number.isSafeInteger(Number(q.value))||q.code in quotas){error.value=`${m.code} 的额度编码必须唯一且为大写编码，额度须为非负安全整数`;return null;}quotas[q.code]=Number(q.value);}result.push({moduleCode:m.code,enabled:m.enabled,quotas});}return result;}
async function save(){if(busy.value||loading.value)return;if(attempt){await send();return;}error.value='';if(!plan.value){if(!/^[A-Z][A-Z0-9_]{1,63}$/.test(form.code)||!form.name.trim()){error.value='请输入合法套餐编码和名称';return;}attempt={kind:'create',key:crypto.randomUUID(),body:{code:form.code,name:form.name.trim()}};}else{const list=modules();if(!list||!form.versionName.trim())return;attempt=selected.value?{kind:'update',id:selected.value.id,key:crypto.randomUUID(),body:{name:form.versionName.trim(),modules:list,version:selected.value.version}}:{kind:'version',id:plan.value.id,key:crypto.randomUUID(),body:{versionNo:form.versionNo,name:form.versionName.trim(),modules:list}};}await send();}
async function publish(){if(busy.value||dirty.value||!selected.value||!confirmed.value)return;if(!attempt)attempt={kind:'publish',id:selected.value.id,key:crypto.randomUUID(),body:{version:selected.value.version}};await send();}
async function send(){if(!attempt||busy.value)return;const a=attempt,token=props.token,wasUnknown=unknown.value;busy.value=true;error.value='';try{const headers={'Idempotency-Key':a.key};const r=a.kind==='create'?await client.POST('/console/packages',{params:{header:headers},body:a.body}):a.kind==='version'?await client.POST('/console/packages/{id}/versions',{params:{path:{id:a.id!},header:headers},body:a.body}):a.kind==='update'?await client.PUT('/console/package-versions/{id}',{params:{path:{id:a.id!},header:headers},body:a.body}):await client.POST('/console/package-versions/{id}/publish',{params:{path:{id:a.id!},header:headers},body:a.body});if(!mounted||token!==props.token)return;if(r.error){unknown.value=wasUnknown||r.response.status>=500;error.value=unknown.value?'操作结果尚未确认，请使用原请求重试；权限变化时联系管理员按套餐编码核对':r.error.error.message;if(!unknown.value)attempt=null;validated.value=false;return;}if(!r.data?.data)throw Error('Unknown result');attempt=null;unknown.value=false;if(a.kind==='create'){plan.value=r.data.data as Plan;applySelection();notice.value='套餐草稿已创建，请配置首个版本';}else{const v=r.data.data as Version;plan.value={...plan.value!,versions:[...plan.value!.versions.filter(x=>x.id!==v.id),v],status:a.kind==='publish'?'ACTIVE':plan.value!.status};applySelection(v);notice.value=a.kind==='publish'?'版本已发布且冻结，可在新建租户中选用。现有订阅保持原版本。':'草稿已保存，请校验后发布';}emit('changed');}catch{if(mounted&&token===props.token){unknown.value=true;error.value='操作结果尚未确认，请使用原请求重试';}}finally{if(mounted&&token===props.token)busy.value=false;}}
async function validate(){if(!selected.value||dirty.value||busy.value||unknown.value)return;busy.value=true;error.value='';const token=props.token;try{const r=await client.POST('/console/package-versions/{id}/validate',{params:{path:{id:selected.value.id}}});if(!mounted||token!==props.token)return;if(r.error){error.value=r.error.error.message;return;}validated.value=r.data.data.valid;confirmed.value=false;if(!validated.value)error.value=r.data.data.errors.join('；');else notice.value='当前保存版本校验通过，发布时服务端会再次核对';}catch{if(mounted&&token===props.token)error.value='校验失败，请重试';}finally{if(mounted&&token===props.token)busy.value=false;}}
onMounted(()=>{void load();firstInput.value?.focus();});onBeforeUnmount(()=>{mounted=false;attempt=null;});
</script>
<template>
<section class="panel package-editor" aria-labelledby="package-editor-title"><h2 id="package-editor-title">{{plan?`套餐配置：${plan.name}`:'新建套餐'}}</h2>
<p v-if="error" ref="errorBox" role="alert" tabindex="-1">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<div class="actions"><button type="button" :disabled="busy||unknown" @click="load">重新读取配置</button><button type="button" :disabled="busy||unknown" @click="emit('close')">关闭套餐配置</button></div><p v-if="loading">正在读取配置…</p>
<form v-if="!plan" @submit.prevent="save"><fieldset :disabled="busy||unknown||loading||!canManage"><label>套餐编码<input ref="firstInput" v-model="form.code" required maxlength="64" pattern="[A-Z][A-Z0-9_]{1,63}"/></label><label>套餐名称<input v-model="form.name" required maxlength="100"/></label></fieldset><button v-if="!unknown" type="submit" :disabled="busy||loading||!canManage">创建套餐草稿</button></form>
<template v-else><p>套餐编码：{{plan.code}} · {{plan.status}}。发布版本不可覆盖，变更请创建新版本。</p><div class="actions"><button v-for="v in plan.versions" :key="v.id" type="button" :disabled="busy||unknown" @click="select(v)">V{{v.versionNo}} {{v.name}} · {{v.status}}</button><button v-if="canManage" type="button" :disabled="busy||unknown||loading" @click="select()">新建版本</button></div>
<form v-if="canManage&&(!selected||selected.status==='DRAFT')" @submit.prevent="save"><fieldset :disabled="busy||unknown||loading"><label>版本号<input v-model.number="form.versionNo" type="number" required min="1" max="2147483647" :disabled="!!selected"/></label><label>版本名称<input v-model="form.versionName" required maxlength="100"/></label><p>勾选有效业务模块。额度填0表示无可用额度，停用模块的额度不生效。配置前请确认对应业务已支持该额度，自定义代码不会自动产生资源限制。</p><p v-if="grants.some(m=>m.code==='SUPPLIER'&&m.enabled)">供应商主体额度使用 SUPPLIER_COUNT，未配置或填0不能新增主体；已退出但保留的主体仍计数。</p><p v-if="!options.length">当前没有有效模块，请联系平台管理员维护模块目录后重新读取。</p>
<div v-for="(m,moduleIndex) in grants" :key="m.code" class="module"><label class="check"><input v-model="m.enabled" type="checkbox"/>{{options.find(o=>o.code===m.code)?.name??m.code}}（{{m.code}}）</label><button v-if="!options.some(o=>o.code===m.code)" type="button" @click="grants.splice(moduleIndex,1)">移除失效模块 {{m.code}}</button><div v-for="(q,index) in m.quotas" :key="index" class="quota-row"><label>额度编码<input v-model="q.code" :aria-label="`${m.code}额度编码${index+1}`" required maxlength="64" pattern="[A-Z][A-Z0-9_]{0,63}"/></label><label>额度上限<input v-model="q.value" :aria-label="`${m.code}额度上限${index+1}`" required inputmode="numeric" pattern="[0-9]+"/></label><button type="button" :aria-label="`删除${m.code}额度${index+1}`" @click="m.quotas.splice(index,1)">删除额度</button></div><button type="button" :aria-label="`添加${m.code}额度`" @click="m.quotas.push({code:'',value:'0'})">添加额度</button></div>
</fieldset><button v-if="!unknown" type="submit" :disabled="busy||loading">{{selected?'保存版本草稿':'创建版本草稿'}}</button></form>
<template v-if="selected"><h3>已保存版本 V{{selected.versionNo}} · {{selected.name}}</h3><ul><li v-for="m in selected.modules" :key="m.moduleCode">{{m.moduleCode}}：{{m.enabled?'启用':'停用'}} · {{JSON.stringify(m.quotas)}}</li></ul><p v-if="selected.status!=='DRAFT'">此版本只读，不能直接修改或再次发布。</p><p v-else-if="dirty">存在未保存修改，请先保存或重新读取。旧校验不能用于发布。</p><template v-else><button v-if="canManage" type="button" :disabled="busy||unknown" @click="validate">校验保存版本</button><label v-if="canPublish" class="check"><input v-model="confirmed" type="checkbox" :disabled="busy||unknown||(canManage&&!validated)"/>确认发布以上已保存模块和额度；现有租户订阅不自动切换</label><button v-if="canPublish&&!unknown" type="button" :disabled="busy||!confirmed||(canManage&&!validated)" @click="publish">发布版本</button></template></template>
</template><button v-if="unknown" type="button" :disabled="busy" @click="send">使用原请求重试</button>
</section>
</template>
<style scoped>
.package-editor{margin-top:20px;max-width:960px;min-width:0;}.package-editor p,.package-editor li{overflow-wrap:anywhere;line-height:1.6;}fieldset{border:0;padding:0;min-width:0;}input:not([type=checkbox]){width:100%;min-width:0;}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0;}.actions button,.module button{width:auto;padding:0 14px;min-height:44px;margin:0;}.check{display:flex;align-items:center;gap:10px;}.check input{width:20px;height:20px;flex-shrink:0;}.module{padding:12px 0;border-bottom:1px solid #c8d2da;}.quota-row{display:grid;grid-template-columns:1fr 1fr auto;gap:10px;align-items:end;}.quota-row label{min-width:0;margin:10px 0;}.quota-row button{margin-bottom:10px;}[role=alert]{color:#a52828;}@media(max-width:600px){.quota-row{grid-template-columns:1fr;gap:0;}.quota-row button{justify-self:start;}}
</style>
